<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
$user=require_permission('settings',($_SERVER['REQUEST_METHOD']??'GET')==='POST'?'edit':'view');$db=admin_db();$error='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST')try{
 verify_csrf();$stored=[];foreach($db->query("SELECT setting_key,value_text FROM settings WHERE setting_key IN ('r2_access_key_id','r2_secret_access_key')")as$item)$stored[$item['setting_key']]=$item['value_text'];$storage='r2';$values=['media_storage'=>'r2','r2_account_id'=>trim((string)($_POST['r2_account_id']??'')),'r2_bucket'=>trim((string)($_POST['r2_bucket']??'')),'r2_public_url'=>rtrim(trim((string)($_POST['r2_public_url']??'')),'/')];
 foreach(['r2_access_key_id','r2_secret_access_key'] as $key)if(trim((string)($_POST[$key]??''))!=='')$values[$key]=encrypt_setting(trim((string)$_POST[$key]));
 if($storage==='r2'&&(!$values['r2_account_id']||!$values['r2_bucket']||!filter_var($values['r2_public_url'],FILTER_VALIDATE_URL)||empty($values['r2_access_key_id'])&&empty($stored['r2_access_key_id'])||empty($values['r2_secret_access_key'])&&empty($stored['r2_secret_access_key'])))throw new RuntimeException('Completa Account ID, bucket, URL pública y ambas claves antes de activar R2.');
 $db->beginTransaction();$save=$db->prepare('INSERT INTO settings(setting_key,value_text,is_public) VALUES(?,?,0) ON DUPLICATE KEY UPDATE value_text=VALUES(value_text),is_public=0');foreach($values as $key=>$value)$save->execute([$key,$value]);if($storage==='r2')r2_test_connection($db);audit($db,(int)$user['id'],'save','web-configuration');$db->commit();flash('success',$storage==='r2'?'R2 conectado y verificado correctamente.':'Configuración Web actualizada.');header('Location: /admin/configuration.php');exit;
}catch(Throwable $exception){if($db->inTransaction())$db->rollBack();$error=$exception->getMessage();}
$settings=[];foreach($db->query("SELECT setting_key,value_text FROM settings WHERE setting_key LIKE 'r2_%' OR setting_key='media_storage'")as$item)$settings[$item['setting_key']]=$item['value_text'];$settings['media_storage']='r2';$flash=pull_flash();try{r2_settings($db);$r2Ready=true;}catch(Throwable){$r2Ready=false;}
